protected void new()
{
    // call service class and service class method
    super(classStr(METGL70EmailFailureService), methodStr(METGL70EmailFailureService, processOperation), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Construct METGL70EmailFailureController class
/// </summary>
public static METGL70EmailFailureController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METGL70EmailFailureController controller;
    controller = new METGL70EmailFailureController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

    public static void main(Args _args)

    {
        METGL70EmailFailureController controller;

        controller = METGL70EmailFailureController::construct();
        controller.parmArgs(_args);
        controller.parmShowDialog(true);
        controller.startOperation();
    }

